// </auto-generated-scaffold>
#nullable enable
using Wolverine.Http;
using Wolverine.Marten;
using Campaigns.Contracts;

namespace Campaigns.Slices.Campaigns;

/// <summary>
/// ONE COMMAND, TWO POSSIBLE EVENTS. The little book allows it and says it should not be the rule; here it
/// is right, because a delivery attempt reports either success or failure and splitting it into two
/// commands would let a caller claim both outcomes for one attempt.
///
/// The rule needs the folded recipient list, so it is enforce="aggregate" and the aggregate handler
/// workflow hands it over.
///
/// A MODELLING GAP, left visible rather than papered over: the model declares no rule for an
/// <c>outcome</c> that is neither delivered nor bounced, and an endpoint has to do something. It refuses
/// with <c>UnknownOutcome</c> — a rule name that exists in this file and nowhere in the model, which is
/// exactly the kind of invention this kit is meant to prevent. It should become a GWT with
/// enforce="periphery"; it is recorded in the folder README rather than quietly fixed here, because
/// adding it to the model is the domain expert's call and not the implementer's.
/// </summary>
public static class RecordOutcomeEndpoint
{
    public const string Route = "/messages/{messageId}/outcome";

    public const string Delivered = "delivered";
    public const string Bounced = "bounced";

    [WolverinePost(Route)]
    public static (IResult, Events) Record(
        RecordOutcome command,
        [WriteAggregate(nameof(RecordOutcome.MessageId), Required = false)] RecordOutcomeState? message)
    {
        var events = new Events();

        // NotARecipient — the rule that needs the FOLD. It also covers a stream that was never queued:
        // an absent message has no recipients, so nobody is one of them. Deliberate, not accidental —
        // one rule name for one rejection, and the detail says which case it was.
        if (message is not { Queued: true })
            return (Rejections.Problem("NotARecipient",
                $"No message {command.MessageId} has been queued, so it has no recipients."), events);

        if (!message.Recipients.Contains(command.Recipient, StringComparer.OrdinalIgnoreCase))
            return (Rejections.Problem("NotARecipient",
                $"'{command.Recipient}' is not a recipient of message {command.MessageId}."), events);

        var outcome = (command.Outcome ?? string.Empty).Trim().ToLowerInvariant();

        object? recorded = outcome switch
        {
            Delivered => new MessageDelivered(command.MessageId, command.Recipient, DateTimeOffset.UtcNow),
            Bounced => new MessageBounced(
                command.MessageId, command.Recipient,
                string.IsNullOrWhiteSpace(command.Reason) ? "unspecified" : command.Reason,
                DateTimeOffset.UtcNow),
            _ => null,
        };

        // See the gap noted above. Resolved into a local first, because a null in an `Events` slot is not
        // "append nothing" — Wolverine hands it to Marten and it surfaces as an ArgumentNullException from
        // inside EventStream.AppendOne, saying nothing about the endpoint that caused it.
        if (recorded is null)
            return (Rejections.Problem("UnknownOutcome",
                $"'{command.Outcome}' is neither '{Delivered}' nor '{Bounced}'."), events);

        events += recorded;
        return (Results.NoContent(), events);
    }
}
